#!/usr/bin/env bash
# ============================================================================
# patch-android-pip.sh — phase 2 ([A5]/[A8]): make the CI-generated android/
# project support Picture-in-Picture.
#
# WHY A PATCH: `android/` is regenerated by `cap add android` on every CI run,
# and a LIBRARY manifest cannot set activity attributes — so
# android:supportsPictureInPicture and the onUserLeaveHint home-press hook
# have to be injected right after `cap sync`, deterministically (the template
# is fixed, so the patch is too). Runs from the repo root.
#
#  1. AndroidManifest.xml → android:supportsPictureInPicture="true" on the
#     MainActivity <activity> (Capacitor's template already carries
#     screenSize|smallestScreenSize|screenLayout in android:configChanges).
#  2. MainActivity.java → onUserLeaveHint sets PipHomeWatcher.HOME_REQUESTED
#     (Home/Recents only — NOT the power button), and
#     onPictureInPictureModeChanged(false) sets PipHomeWatcher.DISMISSED
#     (the plugin turns a real dismissal into the "stop" control event).
# ============================================================================
set -euo pipefail

MANIFEST="android/app/src/main/AndroidManifest.xml"
MAINACT="android/app/src/main/java/com/robonuggets/ytapp/MainActivity.java"

[ -f "$MANIFEST" ] || { echo "patch-android-pip: $MANIFEST missing (run cap add/sync first)" >&2; exit 1; }
[ -f "$MAINACT" ]  || { echo "patch-android-pip: $MAINACT missing" >&2; exit 1; }

# ---- 1. manifest: supportsPictureInPicture on the MainActivity activity ----
python3 - "$MANIFEST" <<'EOF'
import re, sys
p = sys.argv[1]
s = open(p, encoding="utf-8").read()
if "supportsPictureInPicture" in s:
    print("  manifest: supportsPictureInPicture already present")
else:
    # the activity element containing android:name=".MainActivity"
    pat = re.compile(r'(<activity\b[^>]*?android:name="\.MainActivity"[^>]*?)(\s*>)', re.S)
    def add(m):
        return m.group(1) + ' android:supportsPictureInPicture="true"' + m.group(2)
    s2, n = pat.subn(add, s, count=1)
    if n != 1:
        print("  manifest: MainActivity <activity> element not found — NOT patched", file=sys.stderr)
        sys.exit(1)
    open(p, "w", encoding="utf-8").write(s2)
    print("  manifest: supportsPictureInPicture=\"true\" added")
EOF

# ---- 2. MainActivity: home-press watcher + PiP-dismiss signal ----
python3 - "$MAINACT" <<'EOF'
import sys
p = sys.argv[1]
s = open(p, encoding="utf-8").read()
if "PipHomeWatcher" in s:
    print("  MainActivity: PiP hooks already present")
else:
    snippet = """
    // ---- phase 2 (PiP): injected by scripts/patch-android-pip.sh ----
    // Home/Recents leave → the plugin enters PiP (power-button sleeps do NOT
    // fire onUserLeaveHint — that distinction is the whole point).
    @Override
    public void onUserLeaveHint() {
        com.robonuggets.ytbackground.PipHomeWatcher.HOME_REQUESTED = true;
        super.onUserLeaveHint();
    }

    // PiP window gone: expanded-back also lands here, but the plugin clears
    // the flag in handleOnResume; only a real dismissal reaches onStop.
    @Override
    public void onPictureInPictureModeChanged(boolean isInPiPMode) {
        if (!isInPiPMode) {
            com.robonuggets.ytbackground.PipHomeWatcher.DISMISSED = true;
        }
        super.onPictureInPictureModeChanged(isInPiPMode);
    }
"""
    i = s.rstrip().rfind("}")
    if i == -1:
        print("  MainActivity: no closing brace found — NOT patched", file=sys.stderr)
        sys.exit(1)
    body = s.rstrip()
    # if the class body is a bare `{}` → open a body; else append before `}`
    if body.endswith("{}"):
        body = body[:-2] + " {" + snippet + "}\n"
    else:
        body = body[:i].rstrip() + "\n" + snippet + "}\n"
    open(p, "w", encoding="utf-8").write(body)
    print("  MainActivity: onUserLeaveHint + onPictureInPictureModeChanged injected")
EOF

echo "patch-android-pip: done"
